class XmlElementNotFoundError(Exception):
    """ Raised when element is not found in XML file. """
    pass


class ResponsesNotEqualRequestsError(Exception):
    """ Raised when response does not confirm the request. """
    pass


class InvalidEcpriDelayMeasurementSession(Exception):
    """ Raised when eCPRI one-way delay measurement session is invalid. """
    pass


class EcpriDelayThresholdExceeded(Exception):
    """ Raised when eCPRI one-way delay measurement procedure exceeds the threshold. """
    pass


class InvalidEcpriDelayMeasurementIdOrder(Exception):
    """ Raised when 'Measurement ID' field in eCPRI one-way delay measurements is not incremented correctly. """
    pass


class InvalidEcpriDelayTimeStamp(Exception):
    """ Raised when 'Time Stamp' field in eCPRI one-way delay measurement packets is invalid. """
    pass


class InvalidEcpriMsg5Format(Exception):
    """ Raised when eCPRI one-way delay measurement packets (MSG#5) format is invalid. """
    pass


class InvalidEcpriDelayMeasurementActionType(Exception):
    """ Raised when eCPRI one-way delay measurement action type is invalid. """
    pass


class InvalidPeriodicDelayMeasurementSession(Exception):
    """ Raised when eCPRI one-way delay measurement session is invalid. """
    pass


class InvalidPeriodicSessionsNumber(Exception):
    """ Raised when the number of periodic sessions is invalid within time period. """
    pass


class InvalidBtsLogMessageFormat(Exception):
    """ Raised when format of BTS Log message is invalid. """
    pass


class FileConversionError(Exception):
    """
    Raised when file could not be converted.
    """
    pass


class ConversionFilterError(Exception):
    """
    Raised when used incorrect PCAP conversion filter.
    """
    pass


class BipLogDataLoadError(Exception):
    """
    Raised when BIP Log data was not loaded before validation.
    """
    pass


class BipParameterValidationError(Exception):
    """
    Raised when BIP parameter is not validated successfully.
    """
    pass


class McsharkDecoderError(Exception):
    """
    Raised when mcshark decoder cannot be validated.
    """
    pass


class KpiThresholdExceededError(Exception):
    """
    Raised when a KPI threshold is exceeded.
    """
    pass
